<?php
declare(strict_types=1);namespace Atlas\Platform\Resources\Packets;final class WordPressPacketRepository implements PacketRepository{public function __construct(private object$db){}public function create(string$org,int$user,string$name,array$items,string$description=''):string{$p=$this->db->prefix.'atlas_packets';$id=wp_generate_uuid4();$now=gmdate('Y-m-d H:i:s');$this->db->insert($p,['id'=>$id,'organization_id'=>$org===''?null:$org,'owner_user_id'=>$user,'name'=>$name,'description'=>substr($description,0,2000),'status'=>'draft','created_at'=>$now,'updated_at'=>$now],['%s','%s','%d','%s','%s','%s','%s','%s']);foreach($items as$item){$this->addItem($id,$user,$item);}return$id;}public function addItem(string$packetId,int$user,array$item):bool{$found=$this->findForUser($packetId,$user,null);if($found===null){return false;}$table=$this->db->prefix.'atlas_packet_items';$max=$this->db->get_var($this->db->prepare("SELECT MAX(display_order) FROM `{$table}` WHERE packet_id=%s",$packetId));$itemId=trim((string)($item['id']??''));if($itemId===''){return false;}$ok=$this->db->insert($table,['id'=>wp_generate_uuid4(),'packet_id'=>$packetId,'item_type'=>sanitize_key((string)($item['type']??'resource')),'item_id'=>$itemId,'title'=>substr(trim((string)($item['title']??'')),0,255),'display_order'=>((int)$max)+1,'notes'=>substr((string)($item['notes']??''),0,1000)],['%s','%s','%s','%s','%s','%d','%s'])!==false;$this->touch($packetId);return$ok;}public function removeItem(string$packetId,string$itemId,int$user):bool{if($this->findForUser($packetId,$user,null)===null){return false;}$ok=$this->db->delete($this->db->prefix.'atlas_packet_items',['id'=>$itemId,'packet_id'=>$packetId],['%s','%s'])!==false;$this->touch($packetId);return$ok;}public function setStatus(string$packetId,int$user,string$status):bool{if(!in_array($status,['draft','ready','archived'],true)||$this->findForUser($packetId,$user,null)===null){return false;}$ok=$this->db->update($this->db->prefix.'atlas_packets',['status'=>$status,'updated_at'=>gmdate('Y-m-d H:i:s')],['id'=>$packetId],['%s','%s'],['%s'])!==false;return$ok;}public function findForUser(string$id,int$user,?string$org):?array{$p=$this->db->prefix.'atlas_packets';$i=$this->db->prefix.'atlas_packet_items';$packet=$this->db->get_row($this->db->prepare("SELECT * FROM `{$p}` WHERE id=%s AND (owner_user_id=%d OR organization_id=%s) LIMIT 1",$id,$user,(string)$org),ARRAY_A);if(!is_array($packet)){return null;}$items=$this->db->get_results($this->db->prepare("SELECT * FROM `{$i}` WHERE packet_id=%s ORDER BY display_order,id",$id),ARRAY_A);return['packet'=>$packet,'items'=>is_array($items)?$items:[]];}public function listForUser(int$user,?string$org,int$limit=25):array{$p=$this->db->prefix.'atlas_packets';$limit=max(1,min(100,$limit));$rows=$this->db->get_results($this->db->prepare("SELECT p.*,COUNT(i.id) item_count FROM `{$p}` p LEFT JOIN `{$this->db->prefix}atlas_packet_items` i ON i.packet_id=p.id WHERE p.owner_user_id=%d OR p.organization_id=%s GROUP BY p.id ORDER BY p.updated_at DESC LIMIT %d",$user,(string)$org,$limit),ARRAY_A);return is_array($rows)?$rows:[];}private function touch(string$id):void{$this->db->update($this->db->prefix.'atlas_packets',['updated_at'=>gmdate('Y-m-d H:i:s')],['id'=>$id],['%s'],['%s']);}}
